// ✅ Thời gian nằm dưới quyền kiểm soát của test
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

beforeEach(() => {
  vi.useFakeTimers(); // ⏱️ đóng băng setTimeout của component
});
afterEach(() => {
  vi.useRealTimers(); // dọn dẹp — không leak sang test khác
});

test('gọi search API sau khi hết debounce 300ms', async () => {
  // ✅ đồng bộ userEvent với fake clock
  const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
  render(<SearchBox />);

  await user.type(screen.getByRole('textbox'), 'react compiler');
  expect(searchApi).not.toHaveBeenCalled(); // ✅ chắc chắn CHƯA gọi trước 300ms

  act(() => vi.advanceTimersByTime(300));   // tua thời gian thay vì chờ thật
  expect(searchApi).toHaveBeenCalledTimes(1); // ✅ deterministic 100% — local hay CI đều vậy
});

